fe(Sub) -> lookup(?FE_MAP, Sub).
gc(Sub) -> lookup(?GC_MAP, Sub).

lookup(Map, Sub) ->
    case maps:find(Sub, Map) of
        {ok, V} ->
            V;
        error ->
            erlang:error({parse_error, unknown_opcode,
                          iolist_to_binary(io_lib:format("prefix sub-opcode ~B", [Sub]))})
    end.
